def find_largest_product(nums):
    largest = nums[0]
    product = 1
    smallest = abs(nums[0])
    for num in nums:
        product *= num
        if product < 0 and abs(product) > smallest:
            smallest = abs(product)
        if product > largest:
            largest = product
        elif product == 0:
            product = 1
    return largest

nums = [3, -4, 5, -7, 9]
print(find_largest_product(nums))

