import random

def dinner_guests():
    guests = ['Albert Einstein', 'Isaac Newton', 'Marie Curie', 'Galileo Galilei']
    table_seating = {}

    while len(guests) > 0:
        guest = random.choice(guests)
        seated = False
        while not seated:
            table = random.randint(1, 4)

            if table not in table_seating:
                table_seating[table] = [guest]
                seated = True
            elif len(table_seating[table]) == 3:
                table += 1
            else:
                table_seating[table].append(guest)
                seated = True

        guests.remove(guest)

    return table_seating

print(dinner_guests())

